<?php
namespace App\Http\Controllers; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Inertia\Inertia; use Inertia\Response; class WalletController extends Controller { public function index(): Response { return Inertia::render('Wallet/Index', ['transactions'=>request()->user()->walletTransactions()->latest()->paginate(15), 'withdrawals'=>request()->user()->hasMany(\App\Models\Withdrawal::class)->latest()->paginate(10)]); } public function withdraw(Request $request): RedirectResponse { $data=$request->validate(['amount'=>['required','numeric','min:10000'],'bank_name'=>['required','string'],'account_number'=>['required','string'],'account_name'=>['required','string']]); $request->user()->hasMany(\App\Models\Withdrawal::class)->create($data); return back()->with('success','Withdrawal request submitted.'); } }
